    point:     { f: 2, a: [-90, -86, 125, 110, 3, 0, 95, 90, 85, 90] },
    angry:     { f: 5, a: [-92, -96, 145, 100, 35, 80, 102, 92, 78, 88] },
    kick:      { f: 2, a: [-98, -100, 140, 120, 35, 10, 92, 90, 22, -8] },
